  function filterEstimates(){const host=workspace();if(!host)return;const filters=state.estimateFilters||{query:'',status:'',object:''};let visible=0;for(const row of host.querySelectorAll('[data-estimate-id]')){const show=(!filters.query||row.dataset.estimateSearch.includes(filters.query.toLocaleLowerCase('ru-RU')))&&(!filters.status||row.dataset.estimateStatus===filters.status)&&(!filters.object||row.dataset.estimateObject===filters.object);row.hidden=!show;if(show)visible++}const note=host.querySelector('[data-estimate-no-results]');if(note)note.hidden=visible>0||!(state.data?.estimates||[]).length;const count=host.querySelector('[data-estimate-results]');if(count)count.textContent=visible+' из '+(state.data?.estimates||[]).length}
