  async function handleSubmit(event){
    const form=event.target.closest('[data-commercial-form]');if(!form)return;event.preventDefault();if(state.busy||!form.reportValidity())return;
    const type=form.dataset.commercialForm;if(type.startsWith('professional/')){const key=type.slice(13),module=professional()?.find(state.data,key);if(!module)return;const data=professional().parse(form,module);state.edit={type:'professional:'+key,row:data};await perform('/api/commercial/'+type,data);return}
    const data=Object.fromEntries(new FormData(form));
    for(const key of ['id','price_rub','duration_minutes','budget_rub','actual_rub'])if(key in data)data[key]=Number(data[key]);
    for(const key of ['service_id','client_id','assignee_id','object_id'])if(key in data)data[key]=data[key]?Number(data[key]):null;
    if(type==='services'||type==='clients')data.active=form.elements.active.checked;
    for(const key of ['starts_at','ends_at','due_at'])if(key in data)data[key]=data[key]?new Date(data[key]).toISOString():null;
    if(type==='public-profile')data.published=form.elements.published.checked;
    if(type==='estimates'){data.items=estimateItems(form);for(const key of Object.keys(data))if(key.startsWith('line_'))delete data[key]}
    state.edit={type:{services:'service',clients:'client',bookings:'booking',profile:'profile',objects:'object',tasks:'task',shifts:'shift',estimates:'estimate'}[type]||type,row:data};
    const creating=type==='profile'&&!state.data.profile,owner=account();await perform('/api/commercial/'+type,data);if(owner===account()&&creating&&!state.error){state.tab='overview';location.hash='#/work'}
  }
  async function handleChange(event){
    const target=event.target;
    if(target.name==='kind'){syncKindChoices(target.form);const hint=target.form?.querySelector('[data-kind-hint]');if(hint)hint.textContent=(state.data.professional?.catalog||[]).find(row=>row.key===target.value)?.description||'';return}
    if(target.matches('[data-professional-status-filter],[data-professional-chart-filter]')){professional()?.filter(workspace());if(target.matches('[data-professional-chart-filter]')){const chart=workspace()?.querySelector('[data-professional-chart]');if(chart)chart.innerHTML=professional().weightChart(state.data,target.value)}return}
    if(target.name?.startsWith('estimate_')){state.estimateFilters[target.name.slice(9)]=target.value;filterEstimates();return}
    if(target.name==='commercial_organization'){captureDrafts();chooseOrganization(target.value);state.renewKey=null;state.edit=null;state.error='';state.filters={date:'',person:'',status:''};state.data=null;render();try{await load()}catch(error){state.error=error.message;render()}return}
    if(target.name?.startsWith('filter_')){captureDrafts();state.filters[target.name.slice(7)]=target.value;render();return}
    if(target.dataset.memberRole){await perform('/api/commercial/team/role',{user_id:Number(target.dataset.memberRole),role:target.value},{clearDraft:false});return}
    if(target.name==='service_id'&&target.value){const row=state.data.services.find(s=>Number(s.id)===Number(target.value)),form=target.form;if(!row||!form)return;form.elements.title.value=row.title;form.elements.price_rub.value=row.price_rub;form.elements.duration_minutes.value=row.duration_minutes}
    if(target.closest('[data-commercial-form="estimates"]'))estimateTotals(target.form,{verify:true});
  }
  function handleInput(event){if(event.target.name==='estimate_query'){state.estimateFilters.query=event.target.value;filterEstimates();return}if(event.target.matches('[data-professional-search]')){professional()?.filter(workspace());return}if(event.target.closest('[data-commercial-form="estimates"]'))estimateTotals(event.target.form,{verify:true})}
  function homeSummaryMarkup(summary){
    if(!summary?.exists)return '';
    styles();const m=summary.metrics||{},next=summary.next_appointments||[];
    return '<section class="workspaceCard homeWorkSummary" aria-labelledby="homeWorkTitle"><div class="homeWorkHeading"><div><span class="commercialEyebrow">ДЛЯ РАБОТЫ</span><h2 id="homeWorkTitle">'+esc(summary.title)+'</h2><p>'+(summary.active?(summary.trial_active?'Пробный период · ':'Доступ активен · ')+'до '+date(summary.access_until):'Период доступа завершён. Все данные сохранены.')+'</p></div><button class="btn light" type="button" onclick="hpointCommercial.open()">Открыть «Для работы» →</button></div><div class="commercialMetrics">'+metric(m.clients||0,'КЛИЕНТОВ')+metric(m.services||0,'УСЛУГ')+metric(m.planned||0,'ЗАПИСЕЙ В ПЛАНЕ')+metric(money(m.revenue_test_rub),'ВЫПОЛНЕНО РАБОТ')+'</div><div class="homeWorkUpcoming">'+next.map(row=>'<article class="homeWorkAppointment"><div><b>'+esc(row.title)+'</b><small>'+esc(row.client_name)+'</small></div><small>'+date(row.starts_at)+'</small></article>').join('')+'</div></section>';
  }
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.menuOpen){state.menuOpen=false;captureDrafts();render();workspace()?.querySelector('.commercialNavToggle')?.focus();return}if(!event.target.closest?.('.commercialNavPanel')||!event.target.matches?.('button'))return;const nodes=[...workspace().querySelectorAll('.commercialNavPanel button')].filter(node=>node.offsetParent!==null),index=nodes.indexOf(event.target);let next;if(event.key==='ArrowDown')next=(index+1)%nodes.length;else if(event.key==='ArrowUp')next=(index-1+nodes.length)%nodes.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=nodes.length-1;if(next!==undefined){event.preventDefault();nodes[next]?.focus()}});
